const translations = Object.fromEntries(
  (['es', 'fr', 'ja', 'ko', 'pt'] as const).map((language, column) => [
    language,
    Object.fromEntries(rows.map((row) => [row[0], row[column + 1]])),
  ]),
) as Record<AdditionalLanguage, Record<string, string>>;

export function translateInterface(language: InterfaceLanguage, english: string): string {
  if (language === 'en' || language === 'zh-Hant' || language === 'zh-Hans') return english;
  return translations[language][english] ?? english;
}

export function localizeInterfaceMap(
  language: AdditionalLanguage,
  source: Record<string, string>,
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(source).map(([key, value]) => [key, translateInterface(language, value)]),
  );
}

export function localizeInterfaceRecord(
  source: Record<'en' | 'zh-Hant' | 'zh-Hans', string>,
): Record<InterfaceLanguage, string> {
  return {
    ...source,
    es: translateInterface('es', source.en),
    fr: translateInterface('fr', source.en),
    ja: translateInterface('ja', source.en),
    ko: translateInterface('ko', source.en),
    pt: translateInterface('pt', source.en),
  };
}
